-- AI meal recommendations (Premium). The AI only picks from meal_options and the
-- user's favorite_meals; it never invents foods or numbers.

-- Ready-made meals the recommender can suggest. Ingredients use the app's food values
-- (FOOD_DATABASE in nutrition_service.py); totals are computed from them.
CREATE TABLE IF NOT EXISTS public.meal_options (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    name TEXT NOT NULL UNIQUE,
    meal_type TEXT NOT NULL CHECK (meal_type IN ('Breakfast', 'Lunch', 'Dinner', 'Snack')),
    ingredients JSONB NOT NULL,
    active BOOLEAN NOT NULL DEFAULT TRUE,
    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);
ALTER TABLE public.meal_options ENABLE ROW LEVEL SECURITY;

-- Suggestions shown to a user for one local day, kept so reopening the screen doesn't call the AI again.
CREATE TABLE IF NOT EXISTS public.meal_recommendations (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    user_id UUID NOT NULL REFERENCES public.users(id) ON DELETE CASCADE,
    day DATE NOT NULL,
    batch_id UUID NOT NULL,
    name TEXT NOT NULL,
    meal_type TEXT NOT NULL,
    ingredients JSONB NOT NULL,
    calories INTEGER NOT NULL CHECK (calories >= 0),
    proteins_g NUMERIC NOT NULL DEFAULT 0,
    carbs_g NUMERIC NOT NULL DEFAULT 0,
    fats_g NUMERIC NOT NULL DEFAULT 0,
    quantity_g NUMERIC NOT NULL DEFAULT 100,
    reason TEXT,
    source TEXT NOT NULL CHECK (source IN ('ai', 'rules')),
    status TEXT NOT NULL DEFAULT 'pending' CHECK (status IN ('pending', 'added', 'dismissed')),
    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);
CREATE INDEX IF NOT EXISTS meal_recommendations_user_day_idx ON public.meal_recommendations (user_id, day);
ALTER TABLE public.meal_recommendations ENABLE ROW LEVEL SECURITY;
-- No policies on either table: only the backend (service role) reads and writes them.

ON CONFLICT (name) DO NOTHING;
